//go:build integration

package integration

// Shared plumbing for the video flows (video_reels_e2e_test.go,
// video_long_e2e_test.go): fixtures made with ffmpeg at test time, the
// resumable upload, raw (non-envelope) reads of playlists and segments, a
// second-device token, the service log, and tracked skips.
//
// FIXTURES. Nothing binary is committed. Each clip is generated by ffmpeg's
// lavfi sources (testsrc2, sine, color: synthetic, licence-free) into the
// test's temp dir. The e2e "video" tier installs ffmpeg for the media worker
// anyway; without it the flow skips on a developer machine and FAILS where
// the stack is required (missingStack).

import (
	"bytes"
	"context"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/base64"
	"encoding/binary"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
	"testing"
	"time"

	"github.com/google/uuid"
)

// ── Fixtures ────────────────────────────────────────────────────────────

// videoFixture is one generated clip.
type videoFixture struct {
	Bytes   []byte
	Seconds int
	Width   int
	Height  int
}

// requireFFmpeg finds ffmpeg or skips/fails (missingStack).
func requireFFmpeg(t *testing.T) string {
	t.Helper()
	p, err := exec.LookPath("ffmpeg")
	if err != nil {
		missingStack(t, "ffmpeg not on PATH: the video flows generate their fixtures with it (apt-get install ffmpeg)")
	}
	return p
}

// ffmpegFixture runs ffmpeg with args (output path appended) and returns the
// file's bytes.
func ffmpegFixture(t *testing.T, name string, args ...string) []byte {
	t.Helper()
	bin := requireFFmpeg(t)
	out := filepath.Join(t.TempDir(), name)
	full := append([]string{"-hide_banner", "-loglevel", "error", "-y"}, args...)
	full = append(full, out)
	ctx, cancel := context.WithTimeout(context.Background(), 3*time.Minute)
	defer cancel()
	cmd := exec.CommandContext(ctx, bin, full...)
	if msg, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("ffmpeg %s: %v: %s", name, err, strings.TrimSpace(string(msg)))
	}
	b, err := os.ReadFile(out)
	if err != nil || len(b) < 8 || string(b[4:8]) != "ftyp" {
		t.Fatalf("ffmpeg %s: no MP4 written (err=%v, %d bytes)", name, err, len(b))
	}
	return b
}

// reelFixture is a 5 s 360x640 portrait clip with a tone: a Short by both the
// worker's class rule (≤ 600 s) and post-service's (portrait, ≤ 600 s).
// 360 is the worker's minimum short side (processing.MinVideoResolution).
func reelFixture(t *testing.T) videoFixture {
	t.Helper()
	b := ffmpegFixture(t, "reel-5s-portrait.mp4",
		"-f", "lavfi", "-i", "testsrc2=size=360x640:rate=30:duration=5",
		"-f", "lavfi", "-i", "sine=frequency=440:sample_rate=44100:duration=5",
		"-c:v", "libx264", "-preset", "ultrafast", "-pix_fmt", "yuv420p",
		"-c:a", "aac", "-b:a", "64k", "-shortest", "-movflags", "+faststart")
	return videoFixture{Bytes: b, Seconds: 5, Width: 360, Height: 640}
}

// longClassSeconds is just past the shorts boundary
// (processing.ReelMaxDurationSeconds = shared/postclassify
// FlickMaxDurationSeconds = 600 s): the short consumer reads it from the MP4
// header and forwards it to media.events.long
// (cmd/worker/transcode_classes.go classForDuration).
const longClassSeconds = 605

// longFixture is a long-class clip kept small: 605 s at ONE frame a second,
// 1280x720 landscape so the ladder has two rungs (360p, 720p; 1080p is
// above the source and skipped, processing/video.go hlsVariantsFor). The
// worker keeps the source frame rate, so each rendition is ~605 frames.
// A few MB; the file size is printed by the flow. source is a lavfi video
// source ("testsrc2", "testsrc", "smptehdbars"), so two uploads in one run
// are different pictures, not duplicates for the copyright matcher.
func longFixture(t *testing.T, label, source string) videoFixture {
	t.Helper()
	d := strconv.Itoa(longClassSeconds)
	b := ffmpegFixture(t, "long-"+label+".mp4",
		"-f", "lavfi", "-i", source+"=size=1280x720:rate=1:duration="+d,
		"-f", "lavfi", "-i", "sine=frequency=330:sample_rate=8000:duration="+d,
		"-c:v", "libx264", "-preset", "ultrafast", "-crf", "38", "-g", "30", "-pix_fmt", "yuv420p",
		"-c:a", "aac", "-ac", "1", "-b:a", "8k", "-shortest", "-movflags", "+faststart")
	return videoFixture{Bytes: b, Seconds: longClassSeconds, Width: 1280, Height: 720}
}

// overLongFixture is a flat grey clip `seconds` long at one frame a second:
// a few KB however long, refused by the worker's duration cap after probe.
func overLongFixture(t *testing.T, seconds int) videoFixture {
	t.Helper()
	b := ffmpegFixture(t, "over-long.mp4",
		"-f", "lavfi", "-i", fmt.Sprintf("color=c=gray:size=360x640:rate=1:duration=%d", seconds),
		"-c:v", "libx264", "-preset", "ultrafast", "-g", "300", "-pix_fmt", "yuv420p",
		"-movflags", "+faststart")
	return videoFixture{Bytes: b, Seconds: seconds, Width: 360, Height: 640}
}

// padMP4 appends one top-level "free" box so the file is exactly total bytes.
// A free box is valid ISO-BMFF that every reader skips (ffprobe, ffmpeg, the
// worker's MP4Duration box walk), so the clip plays the same; it only makes
// the resumable upload span several 5 MiB parts without a large fixture.
func padMP4(t *testing.T, mp4 []byte, total int) []byte {
	t.Helper()
	pad := total - len(mp4)
	if pad < 8 {
		t.Fatalf("padMP4: clip is %d bytes, cannot pad to %d", len(mp4), total)
	}
	out := make([]byte, 0, total)
	out = append(out, mp4...)
	var hdr [8]byte
	binary.BigEndian.PutUint32(hdr[:4], uint32(pad))
	copy(hdr[4:], "free")
	out = append(out, hdr[:]...)
	return append(out, make([]byte, pad-8)...)
}

// ── Raw HTTP (bodies that are not the JSON envelope) ────────────────────

// rawResp is a non-envelope answer: a playlist, a segment, a chunk ack.
type rawResp struct {
	Status      int
	ContentType string
	Header      http.Header
	Body        []byte
}

// applyAuth sets the same identity headers HTTPClient.Do sends.
func applyAuth(h *HTTPClient, req *http.Request) {
	switch {
	case h == nil:
	case h.BearerOverride != "":
		req.Header.Set("Authorization", "Bearer "+h.BearerOverride)
	case h.UserID != uuid.Nil:
		req.Header.Set("Authorization", "Bearer "+mintToken(h.UserID, ""))
		req.Header.Set("X-User-Id", h.UserID.String())
	}
	if h != nil {
		for k, v := range h.Headers {
			req.Header.Set(k, v)
		}
	}
}

// rawDo sends one request. A path starting with "/" goes to the client's
// base URL (the gateway) with its identity; an absolute URL (a signed
// object-store URL) is fetched with NO identity, as a player does.
func rawDo(t *testing.T, ctx context.Context, h *HTTPClient, method, target string, body []byte, contentType string) rawResp {
	t.Helper()
	full := target
	authed := strings.HasPrefix(target, "/")
	if authed {
		full = h.BaseURL + target
	}
	var rdr io.Reader
	if body != nil {
		rdr = bytes.NewReader(body)
	}
	req, err := http.NewRequestWithContext(ctx, method, full, rdr)
	if err != nil {
		t.Fatalf("build %s %s: %v", method, redactURL(target), err)
	}
	if contentType != "" {
		req.Header.Set("Content-Type", contentType)
	}
	if authed {
		applyAuth(h, req)
	}
	resp, err := (&http.Client{Timeout: 60 * time.Second}).Do(req)
	if err != nil {
		t.Fatalf("%s %s: transport error: %v", method, redactURL(target), err)
	}
	defer resp.Body.Close()
	b, _ := io.ReadAll(io.LimitReader(resp.Body, 64<<20))
	return rawResp{Status: resp.StatusCode, ContentType: resp.Header.Get("Content-Type"), Header: resp.Header, Body: b}
}

// redactURL drops the query (signatures) from a URL for messages.
func redactURL(s string) string {
	if i := strings.IndexByte(s, '?'); i >= 0 {
		return s[:i] + "?[signed]"
	}
	return s
}

// ── Resumable upload ────────────────────────────────────────────────────

type resumableInit struct {
	UploadID   string `json:"upload_id"`
	MediaID    string `json:"media_id"`
	ChunkSize  int    `json:"chunk_size"`
	TotalParts int    `json:"total_parts"`
}

type resumableStatus struct {
	UploadID      string `json:"upload_id"`
	MediaID       string `json:"media_id"`
	TotalBytes    int64  `json:"total_bytes"`
	UploadedBytes int64  `json:"uploaded_bytes"`
	TotalParts    int    `json:"total_parts"`
	Status        string `json:"status"`
	UploadedParts []int  `json:"uploaded_parts"`
}

type chunkAck struct {
	PartNumber    int   `json:"part_number"`
	UploadedBytes int64 `json:"uploaded_bytes"`
	TotalBytes    int64 `json:"total_bytes"`
	AllPartsIn    bool  `json:"all_parts_in"`
}

// resumableStart opens a resumable session (media-service
// internal/http/resumable_handler.go).
func resumableStart(t *testing.T, ctx context.Context, c *HTTPClient, payload []byte) resumableInit {
	t.Helper()
	raw := c.MustOK(t, ctx, "POST", "/v1/media/upload/resumable/init", map[string]any{
		"file_type": "video", "mime_type": "video/mp4", "total_bytes": len(payload),
	})
	var in resumableInit
	if err := json.Unmarshal(raw, &in); err != nil || in.UploadID == "" || in.MediaID == "" || in.ChunkSize <= 0 || in.TotalParts <= 0 {
		t.Fatalf("resumable init: incomplete answer (err=%v raw=%s)", err, string(raw))
	}
	return in
}

// partBytes is part n (1-based) of payload under the session's chunk size.
func partBytes(payload []byte, in resumableInit, n int) []byte {
	start := (n - 1) * in.ChunkSize
	end := start + in.ChunkSize
	if end > len(payload) {
		end = len(payload)
	}
	return payload[start:end]
}

// resumablePut uploads part n through the gateway and returns the ack.
func resumablePut(t *testing.T, ctx context.Context, c *HTTPClient, in resumableInit, payload []byte, n int) chunkAck {
	t.Helper()
	r := rawDo(t, ctx, c, "POST", fmt.Sprintf("/v1/media/upload/resumable/%s/chunk?part_number=%d", in.UploadID, n),
		partBytes(payload, in, n), "application/octet-stream")
	if r.Status != http.StatusOK {
		t.Fatalf("chunk %d: got %d, want 200 (%s)", n, r.Status, trimBody(r.Body))
	}
	var env struct {
		Data chunkAck `json:"data"`
	}
	if err := json.Unmarshal(r.Body, &env); err != nil || env.Data.PartNumber != n {
		t.Fatalf("chunk %d: ack unreadable (err=%v body=%s)", n, err, trimBody(r.Body))
	}
	return env.Data
}

// resumableUploadAll uploads every part in order and completes: the plain,
// uninterrupted path. Returns the media id.
func resumableUploadAll(t *testing.T, ctx context.Context, c *HTTPClient, payload []byte) string {
	t.Helper()
	in := resumableStart(t, ctx, c, payload)
	for n := 1; n <= in.TotalParts; n++ {
		resumablePut(t, ctx, c, in, payload, n)
	}
	c.MustOK(t, ctx, "POST", "/v1/media/upload/resumable/"+in.UploadID+"/complete", nil)
	return in.MediaID
}

func trimBody(b []byte) string {
	s := strings.TrimSpace(string(b))
	if len(s) > 300 {
		s = s[:300] + "..."
	}
	return s
}

// ── Media and post state ────────────────────────────────────────────────

type mediaState struct {
	ProcessingStatus string `json:"processing_status"`
	ModerationStatus string `json:"moderation_status"`
	DurationMs       *int64 `json:"duration_ms"`
}

// mediaStatusOf reads GET /v1/media/:id/status (status code + state).
func mediaStatusOf(ctx context.Context, c *HTTPClient, mediaID string) (int, mediaState, error) {
	env, err := c.Do(ctx, "GET", "/v1/media/"+mediaID+"/status", nil)
	if err != nil {
		return 0, mediaState{}, err
	}
	var s mediaState
	if env.Status == http.StatusOK {
		_ = json.Unmarshal(env.Data, &s)
	}
	return env.Status, s, nil
}

// waitMediaReady polls until ready+passed; fails at once on a terminal state.
func waitMediaReady(t *testing.T, ctx context.Context, c *HTTPClient, mediaID string, timeout time.Duration) mediaState {
	t.Helper()
	var last mediaState
	lastCode := 0
	deadline := time.Now().Add(timeout)
	for {
		code, s, err := mediaStatusOf(ctx, c, mediaID)
		if err == nil {
			last, lastCode = s, code
			if code == http.StatusOK && s.ProcessingStatus == "ready" && s.ModerationStatus == "passed" {
				return s
			}
			if s.ProcessingStatus == "failed" || s.ProcessingStatus == "rejected" || s.ModerationStatus == "rejected" {
				t.Fatalf("media %s stopped at processing_status=%s moderation_status=%s", mediaID, s.ProcessingStatus, s.ModerationStatus)
			}
		}
		if time.Now().After(deadline) {
			t.Fatalf("media %s not ready+passed within %s (last: HTTP %d processing_status=%s moderation_status=%s; is the media worker running with ffmpeg?)",
				mediaID, timeout, lastCode, last.ProcessingStatus, last.ModerationStatus)
		}
		time.Sleep(2 * time.Second)
	}
}

type postState struct {
	ID           string `json:"id"`
	ContentType  string `json:"content_type"`
	Visibility   string `json:"visibility"`
	ReviewStatus string `json:"review_status"`
	IsProcessing bool   `json:"is_processing"`
	Title        string `json:"title"`
}

// createVideoPost creates a flick or long_video post from one media id.
func createVideoPost(t *testing.T, ctx context.Context, c *HTTPClient, contentType, visibility, title, mediaID string) postState {
	t.Helper()
	raw := c.WithHeader("Idempotency-Key", uuid.NewString()).MustOK(t, ctx, "POST", "/v1/posts", map[string]any{
		"text":         "E2E video flow " + title,
		"title":        title,
		"visibility":   visibility,
		"content_type": contentType,
		"media_ids":    []string{mediaID},
	})
	var p postState
	if err := json.Unmarshal(raw, &p); err != nil || p.ID == "" {
		t.Fatalf("create %s post: id missing (err=%v raw=%s)", contentType, err, string(raw))
	}
	if p.ContentType != "" && p.ContentType != contentType {
		t.Fatalf("create post: content_type %q, want %q", p.ContentType, contentType)
	}
	return p
}

// postAs reads GET /v1/posts/:id as c (status + state).
func postAs(ctx context.Context, c *HTTPClient, postID string) (int, postState) {
	env, err := c.Do(ctx, "GET", "/v1/posts/"+postID, nil)
	if err != nil {
		return 0, postState{}
	}
	var p postState
	if env.Status == http.StatusOK {
		_ = json.Unmarshal(env.Data, &p)
	}
	return env.Status, p
}

// waitPostPlayable polls the author's view until the review gate approved the
// post and its media stopped processing (post-service consumers/media.go
// finalizeReviewGate, service/processing.go).
func waitPostPlayable(t *testing.T, ctx context.Context, author *HTTPClient, postID string, timeout time.Duration) postState {
	t.Helper()
	var last postState
	lastCode := 0
	deadline := time.Now().Add(timeout)
	for {
		code, p := postAs(ctx, author, postID)
		last, lastCode = p, code
		if code == http.StatusOK && p.ReviewStatus == "approved" && !p.IsProcessing {
			return p
		}
		if p.ReviewStatus == "rejected" {
			t.Fatalf("post %s was rejected by the review gate", postID)
		}
		if time.Now().After(deadline) {
			t.Fatalf("post %s not approved+playable within %s (last: HTTP %d review_status=%q is_processing=%v; media.events relay and post-service media consumer running?)",
				postID, timeout, lastCode, last.ReviewStatus, last.IsProcessing)
		}
		time.Sleep(2 * time.Second)
	}
}

// ── HLS ─────────────────────────────────────────────────────────────────

// masterPath is the gateway path of an asset's HLS master playlist
// (media-service internal/service/playback.go).
func masterPath(mediaID string) string { return "/v1/media/" + mediaID + "/hls/master.m3u8" }

// playlistLines are the URI lines of an m3u8 body (non-comment, non-blank).
func playlistLines(body []byte) []string {
	var out []string
	for _, l := range strings.Split(string(body), "\n") {
		l = strings.TrimSpace(l)
		if l == "" || strings.HasPrefix(l, "#") {
			continue
		}
		out = append(out, l)
	}
	return out
}

// requirePlaylist asserts a 200 m3u8 answer.
func requirePlaylist(t *testing.T, r rawResp, what string) {
	t.Helper()
	if r.Status != http.StatusOK {
		t.Fatalf("%s: got %d, want 200 (%s)", what, r.Status, trimBody(r.Body))
	}
	if !strings.Contains(strings.ToLower(r.ContentType), "mpegurl") {
		t.Fatalf("%s: Content-Type %q, want application/vnd.apple.mpegurl", what, r.ContentType)
	}
	if !bytes.HasPrefix(bytes.TrimSpace(r.Body), []byte("#EXTM3U")) {
		t.Fatalf("%s: body does not start with #EXTM3U", what)
	}
}

// requireSegment asserts a fetched media segment: 200 and a media type that
// matches its extension (the worker stores .ts as video/MP2T,
// cmd/worker/main.go).
func requireSegment(t *testing.T, r rawResp, uri, what string) {
	t.Helper()
	if r.Status != http.StatusOK {
		t.Fatalf("%s: segment %s got %d, want 200", what, redactURL(uri), r.Status)
	}
	if len(r.Body) == 0 {
		t.Fatalf("%s: segment %s is empty", what, redactURL(uri))
	}
	ct := strings.ToLower(r.ContentType)
	path := uri
	if u, err := url.Parse(uri); err == nil {
		path = u.Path
	}
	switch {
	case strings.HasSuffix(path, ".ts"):
		if ct != "video/mp2t" {
			t.Fatalf("%s: segment %s Content-Type %q, want video/MP2T", what, redactURL(uri), r.ContentType)
		}
	case strings.HasSuffix(path, ".m4s"), strings.HasSuffix(path, ".mp4"):
		if !strings.HasPrefix(ct, "video/") {
			t.Fatalf("%s: segment %s Content-Type %q, want video/*", what, redactURL(uri), r.ContentType)
		}
	default:
		t.Fatalf("%s: segment %s has an unexpected extension", what, redactURL(uri))
	}
}

// playedRung is one variant of the ladder a viewer played.
type playedRung struct {
	Name       string // "360p"
	ChildPath  string
	SegmentURI string // absolute signed URL or gateway path
	Header     http.Header
}

// playAllRungs fetches the master as viewer, then every child playlist and
// its first segment. Returns what it played, keyed by rung name.
func playAllRungs(t *testing.T, ctx context.Context, viewer *HTTPClient, mediaID string) map[string]playedRung {
	t.Helper()
	master := rawDo(t, ctx, viewer, "GET", masterPath(mediaID), nil, "")
	requirePlaylist(t, master, "master playlist")
	children := playlistLines(master.Body)
	if len(children) == 0 {
		t.Fatalf("master playlist lists no variants")
	}
	out := map[string]playedRung{}
	for _, child := range children {
		if !strings.HasPrefix(child, "/v1/media/"+mediaID+"/hls/") || !strings.HasSuffix(child, ".m3u8") {
			t.Fatalf("master lists %q, want /v1/media/%s/hls/<rung>.m3u8", child, mediaID)
		}
		name := strings.TrimSuffix(filepath.Base(child), ".m3u8")
		cr := rawDo(t, ctx, viewer, "GET", child, nil, "")
		requirePlaylist(t, cr, "child playlist "+name)
		segs := playlistLines(cr.Body)
		if len(segs) == 0 {
			t.Fatalf("child playlist %s lists no segments", name)
		}
		seg := rawDo(t, ctx, viewer, "GET", segs[0], nil, "")
		requireSegment(t, seg, segs[0], "rung "+name)
		out[name] = playedRung{Name: name, ChildPath: child, SegmentURI: segs[0], Header: cr.Header}
	}
	return out
}

// segmentExpiry is when a signed segment URL stops working: the
// X-HLS-Expires-At header of its child playlist when present, else the
// X-Amz-Date + X-Amz-Expires of a presigned object URL.
func segmentExpiry(r playedRung) (time.Time, bool) {
	if v := r.Header.Get("X-HLS-Expires-At"); v != "" {
		if ts, err := time.Parse(time.RFC3339, v); err == nil {
			return ts, true
		}
	}
	u, err := url.Parse(r.SegmentURI)
	if err != nil {
		return time.Time{}, false
	}
	q := u.Query()
	signed, err1 := time.Parse("20060102T150405Z", q.Get("X-Amz-Date"))
	secs, err2 := strconv.Atoi(q.Get("X-Amz-Expires"))
	if err1 != nil || err2 != nil {
		return time.Time{}, false
	}
	return signed.Add(time.Duration(secs) * time.Second), true
}

// ── Identity ────────────────────────────────────────────────────────────

// deviceClient is the same user signed in on another device: a separate
// access token (its own sid and iat), so a "resume on the second device"
// read does not share the first device's token.
func deviceClient(base *HTTPClient, device string) *HTTPClient {
	b64 := func(b []byte) string { return base64.RawURLEncoding.EncodeToString(b) }
	header, _ := json.Marshal(map[string]string{"alg": "HS256", "typ": "JWT", "kid": jwtKID()})
	now := time.Now()
	claims, _ := json.Marshal(map[string]any{
		"sub":     base.UserID.String(),
		"user_id": base.UserID.String(),
		"sid":     "e2e-" + device + "-" + uuid.NewString(),
		"typ":     "access",
		"iat":     now.Unix(),
		"exp":     now.Add(time.Hour).Unix(),
	})
	in := b64(header) + "." + b64(claims)
	mac := hmac.New(sha256.New, []byte(jwtSecret()))
	mac.Write([]byte(in))
	c := NewHTTPClient(base.BaseURL, base.UserID)
	return c.WithBearer(in + "." + b64(mac.Sum(nil)))
}

// ── Service log ─────────────────────────────────────────────────────────

// serviceLogPath is the stack's combined service log (run-local.sh output):
// ATPOST_E2E_SERVICE_LOG, else the auth flow's ATPOST_E2E_MAIL_LOG (the same
// services.log in the e2e workflow).
func serviceLogPath() string {
	if p := os.Getenv("ATPOST_E2E_SERVICE_LOG"); p != "" {
		return p
	}
	return os.Getenv("ATPOST_E2E_MAIL_LOG")
}

// serviceLogContains reports whether the service log has a line holding
// every one of parts.
func serviceLogContains(t *testing.T, parts ...string) bool {
	t.Helper()
	p := serviceLogPath()
	if p == "" {
		return false
	}
	b, err := os.ReadFile(p)
	if err != nil {
		return false
	}
	for _, line := range strings.Split(string(b), "\n") {
		hit := true
		for _, s := range parts {
			if !strings.Contains(line, s) {
				hit = false
				break
			}
		}
		if hit {
			return true
		}
	}
	return false
}

// ── Tracked skips ───────────────────────────────────────────────────────

// knownOpen is ATPOST_E2E_KNOWN_OPEN: finding ids (e.g. "lv-1,lv-2") whose
// fix has not landed. Only an assertion tied to one of them may skip.
func knownOpen(id string) bool {
	for _, s := range strings.Split(os.Getenv("ATPOST_E2E_KNOWN_OPEN"), ",") {
		if strings.EqualFold(strings.TrimSpace(s), id) {
			return true
		}
	}
	return false
}

// trackedCheck is an assertion that a known open finding is expected to
// break. Call it inside its own t.Run so a skip covers that one assertion.
//
//   - holds: passes; but if the finding is still listed as open it FAILS,
//     so the skip is removed the day the fix lands (a ratchet, never a
//     silent pass).
//   - does not hold, finding listed: skips as "TRACKED SKIP <id>".
//   - does not hold, finding not listed: fails.
func trackedCheck(t *testing.T, findingID string, holds bool, detail string) {
	t.Helper()
	switch {
	case holds && knownOpen(findingID):
		t.Fatalf("tracked skip %s is stale: the assertion now holds; remove %s from ATPOST_E2E_KNOWN_OPEN (%s)", findingID, findingID, detail)
	case holds:
		return
	case knownOpen(findingID):
		t.Skipf("TRACKED SKIP %s (docs/production-readiness, finding %s still open): %s", findingID, findingID, detail)
	default:
		t.Fatalf("%s (finding %s; if it is open again, list it in ATPOST_E2E_KNOWN_OPEN)", detail, findingID)
	}
}

// envDuration reads a Go duration from env, or the default.
func envDuration(key string, def time.Duration) time.Duration {
	if v := os.Getenv(key); v != "" {
		if d, err := time.ParseDuration(v); err == nil && d > 0 {
			return d
		}
	}
	return def
}

// envInt reads an int from env, or the default.
func envInt(key string, def int) int {
	if v := os.Getenv(key); v != "" {
		if n, err := strconv.Atoi(v); err == nil && n > 0 {
			return n
		}
	}
	return def
}

// containsID reports whether ids holds id.
func containsID(ids []string, id string) bool {
	for _, x := range ids {
		if x == id {
			return true
		}
	}
	return false
}

// listIDs reads ids from a list answer: data as a bare array, or data.items.
func listIDs(raw json.RawMessage) ([]string, error) {
	type item struct {
		ID string `json:"id"`
	}
	var arr []item
	if err := json.Unmarshal(raw, &arr); err != nil {
		var obj struct {
			Items []item `json:"items"`
		}
		if err2 := json.Unmarshal(raw, &obj); err2 != nil {
			return nil, fmt.Errorf("neither an array nor {items}: %v", err)
		}
		arr = obj.Items
	}
	out := make([]string, 0, len(arr))
	for _, it := range arr {
		out = append(out, it.ID)
	}
	return out, nil
}
